package com.example.bookmyticket.config;
import com.example.bookmyticket.entity.*; import com.example.bookmyticket.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.List;
@Configuration public class DataLoader {@Bean CommandLineRunner seed(MovieRepository movies,TheatreRepository theatres,MovieShowRepository shows){return args->{if(movies.count()>0)return;List<Movie> ms=movies.saveAll(List.of(new Movie("The Last Journey","Adventure / Drama","English",132,"A heartfelt adventure about courage and friendship.","https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=700"),new Movie("City of Dreams","Drama / Romance","English",118,"Two strangers meet in a busy city and change each other's lives.","https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=700"),new Movie("Shadow Mission","Action / Thriller","English",145,"An undercover team races against time.","https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=700"),new Movie("Laugh Out Loud","Comedy","Hindi",110,"A light-hearted comedy about family and friendship.","https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=700")));List<Theatre> ts=theatres.saveAll(List.of(new Theatre("PVR Orion Mall","Rajajinagar, Bengaluru"),new Theatre("INOX Central","Malleshwaram, Bengaluru")));for(int d=1;d<=5;d++)for(int i=0;i<ms.size();i++){LocalDate date=LocalDate.now().plusDays(d);for(LocalTime time:List.of(LocalTime.of(10,0),LocalTime.of(14,30),LocalTime.of(19,0)))shows.save(new MovieShow(ms.get(i),ts.get(i%2),LocalDateTime.of(date,time),new BigDecimal("220.00"),48));}};}}
